3	export function nextGeneration(liveCells: Cell[]): Cell[] {
4	  const live = new Set(liveCells.map(toKey));
5	
6	  const neighborCounts = new Map<string, number>();
7	  for (const [x, y] of liveCells) {
8	    for (const [nx, ny] of neighborsOf([x, y])) {
9	      const key = toKey([nx, ny]);
10	      neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
11	    }
12	  }
13	
14	  const survivors: Cell[] = [];
15	  for (const [key, count] of neighborCounts) {
16	    if (count === 3 || (count === 2 && live.has(key))) {
17	      survivors.push(fromKey(key));
18	    }
19	  }
20	  return survivors;
21	}
