23	function neighborsOf([x, y]: Cell): Cell[] {
24	  const offsets = [-1, 0, 1];
25	  return offsets.flatMap((dx) =>
26	    offsets
27	      .filter((dy) => dx !== 0 || dy !== 0)
28	      .map((dy): Cell => [x + dx, y + dy]),
29	  );
30	}
